export const getCreateDocumentUrl = (gymId: number) => {
  return `/api/gyms/${gymId}/documents`;
};

export const createDocument = async (
  gymId: number,
  createDocumentBody: CreateDocumentBody,
  options?: RequestInit,
): Promise<GymDocument> => {
  return customFetch<GymDocument>(getCreateDocumentUrl(gymId), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(createDocumentBody),
  });
};

export const getCreateDocumentMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createDocument>>,
    TError,
    { gymId: number; data: BodyType<CreateDocumentBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof createDocument>>,
  TError,
  { gymId: number; data: BodyType<CreateDocumentBody> },
  TContext
> => {
  const mutationKey = ["createDocument"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createDocument>>,
    { gymId: number; data: BodyType<CreateDocumentBody> }
  > = (props) => {
    const { gymId, data } = props ?? {};

    return createDocument(gymId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CreateDocumentMutationResult = NonNullable<
  Awaited<ReturnType<typeof createDocument>>
>;
export type CreateDocumentMutationBody = BodyType<CreateDocumentBody>;
export type CreateDocumentMutationError = ErrorType<unknown>;

/**
 * @summary Create document or waiver
 */
export const useCreateDocument = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createDocument>>,
    TError,
    { gymId: number; data: BodyType<CreateDocumentBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof createDocument>>,
  TError,
  { gymId: number; data: BodyType<CreateDocumentBody> },
  TContext
> => {
  return useMutation(getCreateDocumentMutationOptions(options));
};
